insert into articles (wp_post_id, slug, title, excerpt, body_html, status, published_at, updated_at, legacy_url, read_time, category_id, cover_url, cover_alt, keywords) values (1530, $wp1530$paradigma-italia-con-anica-alla-mostra-convegno-expocomfort-2024$wp1530$, $wp1530$Paradigma Italia con ANICA alla Mostra Convegno Expocomfort 2024$wp1530$, $wp1530$Siamo orgogliosi di partecipare con ANICA alla Mostra Convegno Expocomfort di Milano: l’appuntamento è mercoledì 13 marzo 2024. L’ INTERVENTO È in programma un intervento curato dal nostro direttore vendite Danilo Giannone, alle ore 16.20, presso il Padiglione 1 area A1. Giannone si occuperà di fornire ai partecipanti un approfondimento dedicato al tema dei sistemi ibridi e degli impianti solari termici in applicazioni residenziali, del settore terziario ed industriale. Non mancherà l’occasione di presentare i valori dell’Ecosistema Paradigma, la sua etica fondata sul rispetto della sostenibilità ambientale e della persona. Paradigma Italia Spa è una società Benefit che opera nel settore della climatizzazione ecologica dal 1998, offrendo una vasta gamma di prodotti quali pannelli solari, pompe di calore e sistemi ibridi, caldaie a condensazione, dispositivi per il trattamento dell’acqua e la termoregolazione. LA PARTNERSHIP L’ azienda aderisce ad ANICA, l’Associazione Nazionale Industrie Caldaie Acciaio, che raggruppa alcune tra le più significative realtà italiane specializzate nel campo del riscaldamento, supportando gli operatori del settore con la divulgazione di formazione specifica e la diffusione delle principali novità riguardanti il risparmio energetico, promuovendo l’accrescimento delle competenze nel rispetto dell’ambiente. IL CONVEGNO Il convegno organizzato dall’associazione nel corso dell’MCE di Milano si concentrerà sui sistemi di riscaldamento per applicazioni commerciali e industriali, e sul concetto di efficienza nella cosiddetta era digitale e delle rinnovabili. L’ appuntamento con la Mostra Convegno Expocomfort è a Milano – Rho Fiera dal 12 al 15 marzo; l’esposizione internazionale rappresenta un punto d’incontro fra le aziende delle energie rinnovabili, dell’efficienza energetica e del mondo acqua, oltre che fra i progettisti e gli installatori. IL COMMENTO “Esserci con ANICA, associazione di cui condividiamo l’impegno per la diffusione di valori di sostenibilità, alla Mostra Convegno Expocomfort – ha commentato il direttore Giannone – Ha per un noi un grande significato. Fra gli intenti di Paradigma c’è sicuramente l’interesse a continuare a sensibilizzare un pubblico di settore sempre più ampio verso i temi del risparmio energetico e del rispetto dell’ambiente.”$wp1530$, $wp1530$<p>Siamo orgogliosi di partecipare con ANICA alla Mostra Convegno Expocomfort di Milano: l’appuntamento è mercoledì 13 marzo 2024.</p>
<h3 id="l-intervento">L’ INTERVENTO</h3>
<p>È in programma un intervento curato dal nostro direttore vendite Danilo Giannone, alle ore 16.20, presso il Padiglione 1 area A1. Giannone si occuperà di fornire ai partecipanti un approfondimento dedicato al tema dei sistemi ibridi e degli impianti solari termici in applicazioni residenziali, del settore terziario ed industriale. Non mancherà l’occasione di presentare i valori dell’Ecosistema Paradigma, la sua etica fondata sul rispetto della sostenibilità ambientale e della persona. Paradigma Italia Spa è una società Benefit che opera nel settore della climatizzazione ecologica dal 1998, offrendo una vasta gamma di prodotti quali pannelli solari, pompe di calore e sistemi ibridi, caldaie a condensazione, dispositivi per il trattamento dell’acqua e la termoregolazione.</p>
<h3 id="la-partnership">LA PARTNERSHIP</h3>
<p>L’ azienda aderisce ad ANICA, l’Associazione Nazionale Industrie Caldaie Acciaio, che raggruppa alcune tra le più significative realtà italiane specializzate nel campo del riscaldamento, supportando gli operatori del settore con la divulgazione di formazione specifica e la diffusione delle principali novità riguardanti il risparmio energetico, promuovendo l’accrescimento delle competenze nel rispetto dell’ambiente.</p>
<h3 id="il-convegno">IL CONVEGNO</h3>
<p>Il convegno organizzato dall’associazione nel corso dell’MCE di Milano si concentrerà sui sistemi di riscaldamento per applicazioni commerciali e industriali, e sul concetto di efficienza nella cosiddetta era digitale e delle rinnovabili. </p>
<p>L’ appuntamento con la Mostra Convegno Expocomfort è a Milano – Rho Fiera dal 12 al 15 marzo; l’esposizione internazionale rappresenta un punto d’incontro fra le aziende delle energie rinnovabili, dell’efficienza energetica e del mondo acqua, oltre che fra i progettisti e gli installatori.</p>
<h3 id="il-commento">IL COMMENTO</h3>
<p>“Esserci con ANICA, associazione di cui condividiamo l’impegno per la diffusione di valori di sostenibilità, alla Mostra Convegno Expocomfort – ha commentato il direttore Giannone – Ha per un noi un grande significato. Fra gli intenti di Paradigma c’è sicuramente l’interesse a continuare a sensibilizzare un pubblico di settore sempre più ampio verso i temi del risparmio energetico e del rispetto dell’ambiente.”</p>
<p> </p>
<p>Fonte: <a href="http://www.paradigmaitalia.it">Paradigma Italia</a></p>$wp1530$, 'published', '2024-04-02T16:10:03', '2025-09-08T11:37:49', $wp1530$https://www.rossimpiantisrl.it/paradigma-italia-con-anica-alla-mostra-convegno-expocomfort-2024/$wp1530$, $wp1530$2 min$wp1530$, (select id from categories where slug='efficienza-energetica-sostenibilita'), null, null, array[$wp1530$Caldaie a condensazione$wp1530$, $wp1530$Fotovoltaico$wp1530$, $wp1530$Risparmio energetico$wp1530$]::text[])
