insert into articles (wp_post_id, slug, title, excerpt, body_html, status, published_at, updated_at, legacy_url, read_time, category_id, cover_url, cover_alt, keywords) values (670, $wp670$portale-per-le-detrazioni-fiscali-al-50-per-ristrutturazioni$wp670$, $wp670$Portale per le detrazioni fiscali al 50% per ristrutturazioni$wp670$, $wp670$Dal 21 novembre è attiva la piattaforma ENEA per la trasmissione delle informazioni per l’accesso alle Detrazioni Fiscali del 50%. Anche per le detrazioni fiscali del 50%, per interventi edilizi e tecnologici diretti al risparmio energetico e/o l’utilizzo di fonti energetiche rinnovabili è richiesta la trasmissione della documentazione, tramite la piattaforma telematica ENEA. Il link è il seguente: Allo stesso indirizzo è visionabile anche una “Guida rapida alla trasmissione” con tutte le informazioni necessarie per l’invio dei dati. Inoltre è importante ricordare che l’invio della documentazione ad ENEA deve avvenire entro il termine di 90 giorni a partire dalla data di ultimazione dei lavori o del collaudo. Soltanto per gli interventi la cui data di fine lavori (collaudo) è compresa tra il 01/01/2018 e l’21/11/2018 il termine dei 90 giorni decorre dal 21/11/2018.$wp670$, $wp670$<p><strong>Dal 21 novembre è attiva la piattaforma ENEA per la trasmissione delle informazioni per l’accesso alle Detrazioni Fiscali del 50%.</strong></p>
<p>Anche per le detrazioni fiscali del 50%, per interventi edilizi e tecnologici diretti al risparmio energetico e/o l’utilizzo di fonti energetiche rinnovabili è richiesta la trasmissione della documentazione, tramite la piattaforma telematica ENEA. </p>
<p>Il link è il seguente: <a href="http://paradigmaitalia.musvc5.net/e/t?q=A%3dLdHYPa%26t%3dY%269%3dUHgO%26I%3dDYRX%263%3dFENx_PlwX_av_LY1k_Vn_PlwX_Z1Q5U.v71.C99i.GE_LY1k_VnP4M2PFN2SC58G0Hq-CyCtGKCm_PlwX_Z1%268%3du9v5iSDPkc.992%26GD%3dUBaR" rel="noopener noreferrer" target="_blank">http://www.acs.enea.it/ristrutturazioni-edilizie/ </a></p>
<p>Allo stesso indirizzo è visionabile anche una “Guida rapida alla trasmissione” con tutte le informazioni necessarie per l’invio dei dati.</p>
<p>Inoltre è importante ricordare che l’invio della documentazione ad ENEA deve avvenire<strong> entro il termine di 90 giorni</strong> a partire dalla data di ultimazione dei lavori o del collaudo. </p>
<p>Soltanto per gli interventi la cui data di fine lavori (collaudo) è compresa tra il 01/01/2018 e l’21/11/2018 il termine dei 90 giorni decorre dal 21/11/2018.</p>
<p> </p>
<p>Fonte: <a href="http://www.paradigmaitalia.it">Paradigma Italia</a></p>$wp670$, 'published', '2021-01-26T17:10:03', '2025-09-08T11:37:50', $wp670$https://www.rossimpiantisrl.it/portale-per-le-detrazioni-fiscali-al-50-per-ristrutturazioni/$wp670$, $wp670$1 min$wp670$, (select id from categories where slug='efficienza-energetica-sostenibilita'), null, null, array[$wp670$Caldaie a condensazione$wp670$, $wp670$Fotovoltaico$wp670$, $wp670$Risparmio energetico$wp670$]::text[])
